import sys
from heapq import heappush, heappop

def min_days_to_pass_exams(n, m, exams, preparation):
    exams_to_prepare = {}
    days_passed = 0
    available_days = []

    for day, subject in enumerate(exams):
        if subject != 0:
            if subject in exams_to_prepare:
                exams_to_prepare[subject].append(day)
            else:
                exams_to_prepare[subject] = [day]

        while available_days and available_days[0] <= day:
            heappop(available_days)

        if subject == 0:
            heappush(available_days, day + 1)

        while exams_to_prepare and available_days:
            next_subject = max(exams_to_prepare, key=lambda x: exams_to_prepare[x])
            next_day = exams_to_prepare[next_subject].pop(0)

            if next_day <= available_days[0]:
                days_passed = max(days_passed, next_day + preparation[next_subject - 1] - 1)
                heappop(available_days)
            else:
                break

        if not exams_to_prepare and not available_days:
            return -1

    return days_passed

