import heapq

def solve_exams(n, m, exams, preparation):
    exams_to_pass = [[] for _ in range(m + 1)]
    for day, subject in enumerate(exams, 1):
        if subject != 0:
            exams_to_pass[subject].append(day)

    heap = []
    current_day = 0
    passed_exams = 0

    for day in range(1, n + 1):
        current_day = day

        if exams[day - 1] != 0:
            subject = exams[day - 1]
            if exams_to_pass[subject]:
                exams_to_pass[subject].pop(0)
                passed_exams += 1
            elif not heap:
                return -1
            else:
                next_day, prev_subject = heapq.heappop(heap)
                exams_to_pass[prev_subject].pop(0)
                passed_exams += 1
        elif heap:
            next_day, prev_subject = heapq.heappop(heap)
            exams_to_pass[prev_subject].pop(0)
            passed_exams += 1

        if exams[day - 1] != 0 and exams_to_pass[exams[day - 1]]:
            next_available = exams_to_pass[exams[day - 1]][0]
            heapq.heappush(heap, (next_available + preparation[exams[day - 1] - 1], exams[day - 1]))

    while heap:
        next_day, subject = heapq.heappop(heap)
        if next_day > current_day:
            current_day = next_day
        exams_to_pass[subject].pop(0)
        passed_exams += 1

    return current_day if passed_exams == m else -1

def main():
    n, m = map(int, input().split())
    exams = list(map(int, input().split()))
    preparation = list(map(int, input().split()))

    result = solve_exams(n, m, exams, preparation)
    print(result)

if __name__ == "__main__":
    main()

import heapq
from typing import List, Tuple

def min_days_to_pass_exams(n: int, m: int, d: List[int], a: List[int]) -> int:
    exams = [0] * (m + 1)
    for day, subject in enumerate(d, 1):
        if subject > 0:
            exams[subject] = day

    heap: List[Tuple[int, int]] = []
    day = 0
    passed = 0

    while day < n and passed < m:
        day += 1
        if exams[d[day - 1]] == day:
            heapq.heappush(heap, (-day, d[day - 1]))

        while heap and day - exams[heap[0][1]] >= a[heap[0][1] - 1]:
            _, subject = heapq.heappop(heap)
            passed += 1

    while heap:
        _, subject = heapq.heappop(heap)
        if day - exams[subject] >= a[subject - 1]:
            passed += 1
            day += 1
        else:
            break

    return day if passed == m else -1

if __name__ == "__main__":
    n, m = map(int, input().split())
    d = list(map(int, input().split()))
    a = list(map(int, input().split()))
    print(min_days_to_pass_exams(n, m, d, a))
